"""Auto-generated Model Cards.

Generates a Model Card (per Google's Model Cards paper, Mitchell et al. 2019)
for every model version in the registry. The card is stored as a Markdown
artifact in MinIO/S3 and surfaced via the API.

A Model Card includes:
  - Model details (name, version, owner, date)
  - Intended use (what the model predicts, for whom)
  - Training data (dataset card reference, size, time range)
  - Evaluation data (held-out test set description)
  - Quantitative metrics (accuracy, calibration ECE, latency)
  - Ethical considerations (bias, limitations)
  - Caveats and recommendations
"""
from __future__ import annotations

from datetime import datetime, timezone
from typing import Any

from pydantic import BaseModel, Field


class ModelCard(BaseModel):
    """A Model Card for a deployed prediction model."""

    model_name: str
    model_version: str
    model_uri: str | None = None
    owner: str = "VaxGenesis AI"
    date: str = Field(default_factory=lambda: datetime.now(timezone.utc).strftime("%Y-%m-%d"))

    # Intended use
    intended_use: str = ""
    intended_users: list[str] = Field(default_factory=list)
    out_of_scope_uses: list[str] = Field(default_factory=list)

    # Training data
    training_data_name: str = ""
    training_data_size: int | None = None
    training_data_card_uri: str | None = None

    # Evaluation
    evaluation_data_name: str = ""
    evaluation_metrics: dict[str, float] = Field(default_factory=dict)
    calibration_ece: float | None = None

    # Ethical considerations
    bias_known: bool = False
    bias_description: str | None = None
    limitations: list[str] = Field(default_factory=list)

    # Caveats
    caveats: str = ""

    def to_markdown(self) -> str:
        """Render the Model Card as Markdown."""
        lines = [
            f"# Model Card: {self.model_name} v{self.model_version}",
            "",
            f"**Owner:** {self.owner}  ",
            f"**Date:** {self.date}  ",
            f"**Model URI:** `{self.model_uri or 'N/A'}`",
            "",
            "## Intended Use",
            "",
            self.intended_use or "_Not specified._",
            "",
            f"**Intended users:** {', '.join(self.intended_users) or 'N/A'}",
            "",
            f"**Out-of-scope uses:** {', '.join(self.out_of_scope_uses) or 'N/A'}",
            "",
            "## Training Data",
            "",
            f"- **Dataset:** {self.training_data_name or 'N/A'}",
            f"- **Size:** {self.training_data_size or 'N/A'} samples",
            f"- **Dataset Card:** `{self.training_data_card_uri or 'N/A'}`",
            "",
            "## Evaluation",
            "",
            f"- **Test set:** {self.evaluation_data_name or 'N/A'}",
            "",
            "| Metric | Value |",
            "|--------|-------|",
        ]
        for metric, value in self.evaluation_metrics.items():
            lines.append(f"| {metric} | {value:.4f} |")
        if self.calibration_ece is not None:
            lines.append(f"| Calibration ECE | {self.calibration_ece:.4f} |")

        lines.extend([
            "",
            "## Ethical Considerations",
            "",
            f"**Known bias:** {'Yes' if self.bias_known else 'No'}",
        ])
        if self.bias_description:
            lines.append(f"  {self.bias_description}")
        if self.limitations:
            lines.append("")
            lines.append("**Limitations:**")
            for lim in self.limitations:
                lines.append(f"- {lim}")

        lines.extend([
            "",
            "## Caveats and Recommendations",
            "",
            self.caveats or "_None._",
            "",
            "---",
            f"*This Model Card was auto-generated by VaxGenesis AI v2.0 on {self.date}.*",
        ])
        return "\n".join(lines)


class ModelCardGenerator:
    """Generates Model Cards from MLflow run metadata + module catalog."""

    # Default intended-use templates per module category
    _INTENDED_USE_TEMPLATES = {
        "hla_binding": "Predicts peptide-HLA binding affinity (IC50) for MHC-I and MHC-II alleles. "
                       "Intended for prioritizing epitopes in multi-epitope vaccine design.",
        "epitope_prediction": "Predicts CTL, HTL, and B-cell epitopes from antigen sequences. "
                              "Intended for epitope inventory generation in vaccine construct assembly.",
        "toxicity_prediction": "Predicts toxic, hemolytic, and inflammatory peptide properties. "
                               "Intended for safety screening of candidate epitopes.",
        "structural_biology": "Predicts 3D protein structure via AlphaFold3. "
                              "Intended for structure-based epitope confirmation and docking studies.",
        "default": "Predicts vaccine-relevant properties. Intended for computational vaccinology research.",
    }

    def generate(
        self,
        model_name: str,
        model_version: str,
        metrics: dict[str, float],
        training_data_size: int | None = None,
        training_data_name: str = "",
        model_uri: str | None = None,
    ) -> ModelCard:
        """Generate a Model Card from available metadata."""
        template_key = model_name if model_name in self._INTENDED_USE_TEMPLATES else "default"
        intended_use = self._INTENDED_USE_TEMPLATES[template_key]

        # Known limitations per model type
        limitations = [
            "Predictions are not experimental evidence; wet-lab validation is required.",
            "Model performance may degrade on out-of-distribution inputs.",
        ]
        if model_name in {"hla_binding", "epitope_prediction"}:
            limitations.append(
                "Training data over-represents European-ancestry HLA alleles; "
                "predictions for under-represented populations have higher uncertainty."
            )

        return ModelCard(
            model_name=model_name,
            model_version=model_version,
            model_uri=model_uri,
            intended_use=intended_use,
            intended_users=["vaccine researchers", "computational biologists"],
            out_of_scope_uses=[
                "clinical diagnosis",
                "direct patient treatment decisions",
                "regulatory submission without wet-lab validation",
            ],
            training_data_name=training_data_name or "IEDB + UniProt curated",
            training_data_size=training_data_size,
            evaluation_metrics=metrics,
            calibration_ece=metrics.get("ece"),
            bias_known=model_name in {"hla_binding", "epitope_prediction"},
            bias_description=(
                "Training data over-represents European-ancestry HLA alleles."
                if model_name in {"hla_binding", "epitope_prediction"} else None
            ),
            limitations=limitations,
            caveats=(
                "This model is part of an integrated pipeline. Individual "
                "predictions should be interpreted in the context of the full "
                "candidate evaluation, not in isolation."
            ),
        )
